def parse_spec(spec):
    """`name` or `name:arg` into (function, arg); the argument is everything after the first colon."""
    name, _, arg = spec.partition(":")
    if name not in TRANSFORMS:
        raise TabulaError("unknown transform %r" % name)
    return TRANSFORMS[name], (arg if ":" in spec else None)


def apply_transforms(value, specs):
    for fn, arg in specs:
        value = fn(value, arg)
    return value


# --- commands ------------------------------------------------------------------------------------------------

def _need_args(args, count, usage, at_least=False):
    if len(args) < count if at_least else len(args) != count:
        raise UsageError("usage: %s %s" % (PROG, usage))


def _cell_number(table, row_number, column, value):
    """The Decimal in a cell; a TabulaError naming the file, the row (from 1, file order) and the column if it is none."""
    try:
        return _need_number(value)
    except TabulaError as exc:
        raise TabulaError("%s: row %d: column %r: %s" % (table.source, row_number, column, exc))


def cmd_show(args, opts):
    _need_args(args, 1, "show FILE")
    return load(args[0])


def cmd_head(args, opts):
    _need_args(args, 2, "head FILE N")
    if not args[1].isdigit():
        raise UsageError("head: N must be a whole number, got %r" % args[1])
    table = load(args[0])
    return table.with_rows(table.rows[:int(args[1])])


def cmd_cols(args, opts):
    _need_args(args, 1, "cols FILE")
    table = load(args[0])
    return Table(["position", "column"], [[str(i + 1), name] for i, name in enumerate(table.columns)], table.source)


def cmd_apply(args, opts):
    if len(args) < 3:
        raise UsageError("usage: %s apply FILE COLUMN TRANSFORM..." % PROG)
    table = load(args[0])
    at = table.index(args[1])
    specs = [parse_spec(s) for s in args[2:]]
    rows = []
    for number, row in enumerate(table.rows, 1):
        row = list(row)
        try:
            row[at] = apply_transforms(row[at], specs)
        except TabulaError as exc:
            raise TabulaError("%s: row %d: %s" % (table.source, number, exc))
        rows.append(row)
    return table.with_rows(rows)


def _parse_key(key):
    """`COLUMN[:num][:desc]` (modifiers in either order) into (column, numeric, descending)."""
    column, *mods = key.split(":")
    if not column:
        raise UsageError("sort: empty column name in key %r" % key)
    for mod in mods:
        if mod not in ("num", "desc"):
            raise UsageError("sort: unknown modifier %r in key %r (use num or desc)" % (mod, key))
    if len(set(mods)) != len(mods):
        raise UsageError("sort: modifier given twice in key %r" % key)
    return column, "num" in mods, "desc" in mods


def cmd_sort(args, opts):
    _need_args(args, 2, "sort FILE KEY...", at_least=True)
    keys = [_parse_key(k) for k in args[1:]]
    table = load(args[0])
    keys = [(table.index(column), column, numeric, desc) for column, numeric, desc in keys]
    for at, column, numeric, _ in keys:
        if numeric:
            for number, row in enumerate(table.rows, 1):
                _cell_number(table, number, column, row[at])
    rows = list(table.rows)
    for at, column, numeric, desc in reversed(keys):
        rows.sort(key=(lambda r, at=at: to_decimal(r[at])) if numeric else (lambda r, at=at: r[at]), reverse=desc)
    return table.with_rows(rows)


FILTER_OPERATORS = ("==", "!=", ">=", "<=", ">", "<", "~")  # at one position the longer one is tried first


def _parse_condition(text):
    """`COLUMN OP VALUE` into (column, operator, value): the operator is the first one in the text, the longer on a tie."""
    for at in range(len(text)):
        for op in FILTER_OPERATORS:
            if text.startswith(op, at):
                if at == 0:
                    raise UsageError("filter: no column name before the operator in %r" % text)
                return text[:at], op, text[at + len(op):]
    raise UsageError("filter: no operator (one of %s) in %r" % (" ".join(FILTER_OPERATORS), text))


def _holds(cell, op, value, number):
    """Whether one cell satisfies one condition; `number` is the Decimal of VALUE or None."""
    if op == "~":
        return _icontains(cell, value)
    left = to_decimal(cell) if number is not None else None
    a, b = (left, number) if left is not None else (cell, value)
    return {"==": a == b, "!=": a != b, ">=": a >= b, "<=": a <= b, ">": a > b, "<": a < b}[op]


def cmd_filter(args, opts):
    _need_args(args, 2, "filter FILE CONDITION...", at_least=True)
    conditions = [_parse_condition(c) for c in args[1:]]
    table = load(args[0])
    tests = [(table.index(column), op, value, to_decimal(value)) for column, op, value in conditions]
    return table.with_rows([r for r in table.rows if all(_holds(r[at], op, value, num) for at, op, value, num in tests)])


GROUP_NUMERIC = ("sum", "min", "max", "mean")


def _parse_aggregate(arg):
    """`count` or `KIND:COLUMN` into (kind, column or None)."""
    kind, colon, column = arg.partition(":")
    if kind == "count" and not colon:
        return kind, None
    if kind in GROUP_NUMERIC and colon and column:
        return kind, column
    raise UsageError("group: unknown aggregate %r (use count, sum:COLUMN, min:COLUMN, max:COLUMN or mean:COLUMN)" % arg)


def _aggregate(kind, numbers):
    """The cell text for one aggregate over a group's Decimals (exact: the caller sets the precision)."""
    if kind == "count":
        return str(len(numbers))
    if kind == "mean":
        return fmt_decimal(_round_half_up(sum(numbers, Decimal(0)) / len(numbers), 2))
    return fmt_decimal({"sum": lambda n: sum(n, Decimal(0)), "min": min, "max": max}[kind](numbers))


def cmd_group(args, opts):
    _need_args(args, 3, "group FILE BY AGGREGATE...", at_least=True)
    if len(set(args[2:])) != len(args[2:]):
        raise UsageError("group: the same aggregate is given twice")
    aggregates = [(arg, *_parse_aggregate(arg)) for arg in args[2:]]
    table = load(args[0])
    by = table.index(args[1])
    columns = [args[1]] + [arg.replace(":", "_") for arg, _, _ in aggregates]
    for at, name in enumerate(columns[1:], 1):
        if name in columns[:at]:
            raise TabulaError("%s: result column %r would appear twice" % (table.source, name))
    sources = [None if column is None else table.index(column) for _, _, column in aggregates]
    groups = {}
    for number, row in enumerate(table.rows, 1):
        values = []
        for (_, kind, column), at in zip(aggregates, sources):
            values.append(None if at is None else _cell_number(table, number, column, row[at]))
        groups.setdefault(row[by], []).append(values)
    digits = sum(len(row[at]) for row in table.rows for at in sources if at is not None)
    with localcontext() as ctx:
        ctx.prec = max(getcontext().prec, digits + len(str(len(table))) + 20)  # every digit kept: sums and means are exact
        rows = [[key] + [_aggregate(kind, [v[i] for v in members] if kind != "count" else members)
                         for i, (_, kind, _) in enumerate(aggregates)] for key, members in groups.items()]
    return Table(columns, rows, table.source)


def cmd_join(args, opts):
    _need_args(args, 3, "join LEFT RIGHT KEY")
    left, right = load(args[0]), load(args[1])
    left_key, right_key = left.index(args[2]), right.index(args[2])
    kept = [at for at in range(len(right.columns)) if at != right_key]
    columns = list(left.columns)
    for at in kept:
        name = right.columns[at]
        name = name + "_right" if name in left.columns else name
        if name in columns:
            raise TabulaError("join: the result would have column %r twice" % name)
        columns.append(name)
    matches = {}
    for row in right.rows:
        matches.setdefault(row[right_key], []).append([row[at] for at in kept])
    blank = [[""] * len(kept)] if opts.get("kind") == "left" else []
    rows = [row + extra for row in left.rows for extra in matches.get(row[left_key], blank)]
    return Table(columns, rows, left.source)


def cmd_pivot(args, opts):
    _need_args(args, 4, "pivot FILE ROW COLUMN VALUE")
    if args[1] == args[2]:
        raise UsageError("pivot: ROW and COLUMN must be different columns, got %r twice" % args[1])
    table = load(args[0])
    row_at, column_at, value_at = table.index(args[1]), table.index(args[2]), table.index(args[3])
    cells, column_values = {}, {}
    for number, row in enumerate(table.rows, 1):
        label = row[column_at]
        if not label.strip():
            raise TabulaError("%s: row %d: column %r: empty value" % (table.source, number, args[2]))
        if label == args[1]:
            raise TabulaError("%s: row %d: column %r: value %r is the name of the row column" % (table.source, number, args[2], label))
        column_values[label] = None
        cells.setdefault(row[row_at], {}).setdefault(label, []).append(_cell_number(table, number, args[3], row[value_at]))
    digits = sum(len(row[value_at]) for row in table.rows)
    with localcontext() as ctx:
        ctx.prec = max(getcontext().prec, digits + len(str(len(table))) + 20)  # every digit kept: sums are exact
        rows = [[key] + [fmt_decimal(sum(by_column.get(label, ()), Decimal(0))) for label in column_values]
                for key, by_column in cells.items()]
    return Table([args[1]] + list(column_values), rows, table.source)


def cmd_dedupe(args, opts):
    _need_args(args, 2, "dedupe FILE KEY...", at_least=True)
    table = load(args[0])
    at = [table.index(key) for key in args[1:]]
    stays = {}  # key cells -> position of the row that stays (the first or the last seen)
    for number, row in enumerate(table.rows):
        key = tuple(row[i] for i in at)
        if opts["keep"] == "last" or key not in stays:
            stays[key] = number
    stay = set(stays.values())
    return table.with_rows([row for number, row in enumerate(table.rows) if number in stay])


def _median(numbers):
    """The median of sorted Decimals; an even count gives the exact mean of the two middle ones."""
    middle, odd = divmod(len(numbers), 2)
    return numbers[middle] if odd else (numbers[middle - 1] + numbers[middle]) / 2


def cmd_stats(args, opts):
    _need_args(args, 2, "stats FILE COLUMN...", at_least=True)
    table = load(args[0])
    at = [table.index(column) for column in args[1:]]
    found = []
    for column, i in zip(args[1:], at):
        found.append([_cell_number(table, number, column, row[i])
                      for number, row in enumerate(table.rows, 1) if row[i].strip()])
    digits = sum(len(row[i]) for row in table.rows for i in at)
    rows = []
    with localcontext() as ctx:
        ctx.prec = max(getcontext().prec, digits + len(str(len(table))) + 20)  # every digit kept: sums and means are exact
        for column, numbers in zip(args[1:], found):
            if not numbers:
                rows.append([column, "0", "", "", "", ""])
                continue
            numbers.sort()
            mean = sum(numbers, Decimal(0)) / len(numbers)
            rows.append([column, str(len(numbers)), fmt_decimal(numbers[0]), fmt_decimal(numbers[-1]),
                         fmt_decimal(_round_half_up(mean, 2)), fmt_decimal(_round_half_up(_median(numbers), 2))])
    return Table(["column", "count", "min", "max", "mean", "median"], rows, table.source)


COMMANDS = {
    "show": (cmd_show, "show FILE", "print a table"),
    "head": (cmd_head, "head FILE N", "the first N rows"),
    "cols": (cmd_cols, "cols FILE", "the column names, numbered"),
    "apply": (cmd_apply, "apply FILE COLUMN TRANSFORM...", "run transforms over one column"),
    "sort": (cmd_sort, "sort FILE KEY...", "sort rows by one or more keys"),
    "filter": (cmd_filter, "filter FILE CONDITION...", "keep the rows where every condition holds"),
    "group": (cmd_group, "group FILE BY AGGREGATE...", "one row per BY value with counts, sums, minima, maxima, means"),
    "join": (cmd_join, "join LEFT RIGHT KEY", "join two files on a column, inner or left"),
    "pivot": (cmd_pivot, "pivot FILE ROW COLUMN VALUE", "turn the values of COLUMN into columns of sums of VALUE"),
    "dedupe": (cmd_dedupe, "dedupe FILE KEY...", "drop rows whose KEY values repeat, keeping the first or the last"),
    "stats": (cmd_stats, "stats FILE COLUMN...", "count, min, max, mean and median of numeric columns"),
}


# --- the command line ----------------------------------------------------------------------------------------

def usage_text():
    lines = ["usage: %s [--format text|csv|json] [--kind inner|left] [--keep first|last] COMMAND ARGS..." % PROG, "", "commands:"]
    width = max(len(u) for _, u, _ in COMMANDS.values())
    for _, use, what in COMMANDS.values():
        lines.append("  %s  %s" % (use.ljust(width), what))
    return "\n".join(lines) + "\n"


def parse_args(argv):
    """(command, positional arguments, options) from the command line."""
    opts, rest, i = {name: values[0] for name, values in OPTIONS.items()}, [], 0
    while i < len(argv):
        arg = argv[i]
        name, has_value, value = arg[2:].partition("=") if arg.startswith("--") else (None, False, None)
        if arg in ("-h", "--help"):
            opts["help"] = True
        elif name in OPTIONS:
            if not has_value:
                i += 1
                if i >= len(argv):
                    raise UsageError("--%s needs a value" % name)
                value = argv[i]
            if value not in OPTIONS[name]:
                raise UsageError("--%s must be one of %s, got %r" % (name, ", ".join(OPTIONS[name]), value))
            opts[name] = value
        elif arg.startswith("-") and len(arg) > 1:
            raise UsageError("unknown option %s" % arg)
        else:
            rest.append(arg)
        i += 1
    if opts.get("help"):
        return None, rest, opts
    if not rest:
        raise UsageError("no command given")
    if rest[0] not in COMMANDS:
        raise UsageError("unknown command %r" % rest[0])
    return rest[0], rest[1:], opts


def main(argv=None):
    argv = sys.argv[1:] if argv is None else list(argv)
    try:
        name, args, opts = parse_args(argv)
        if name is None:
            sys.stdout.write(usage_text())
            return 0
        table = COMMANDS[name][0](args, opts)
        sys.stdout.write(render(table, opts["format"]))
        sys.stdout.flush()
        return 0
    except UsageError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 2
    except TabulaError as exc:
        print("%s: %s" % (PROG, exc), file=sys.stderr)
        return 1
    except BrokenPipeError:
        return 0
    except OSError as exc:  # stdout cannot be written (a full disk, say)
        try:
            os.dup2(os.open(os.devnull, os.O_WRONLY), sys.stdout.fileno())  # so the exit flush stays quiet
        except (OSError, ValueError, AttributeError):
            pass
        print("%s: cannot write output: %s" % (PROG, exc.strerror or exc), file=sys.stderr)
        return 1

